import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Live Chat","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/live-chat"}]]},"headers":[],"relativePath":"user-guide/live-chat.md","filePath":"user-guide/live-chat.md","lastUpdated":1790204574000}'),n={name:"user-guide/live-chat.md"};function s(r,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="live-chat" tabindex="-1">Live Chat <a class="header-anchor" href="#live-chat" aria-label="Permalink to &quot;Live Chat&quot;">​</a></h1><p>Install <strong>Live Chat</strong> from Marketplace (free). Open <strong>Communication → Live Chat</strong> for the agent desk. Configure the widget under <strong>Settings → Live Chat</strong>.</p><h2 id="widget-setup" tabindex="-1">Widget setup <a class="header-anchor" href="#widget-setup" aria-label="Permalink to &quot;Widget setup&quot;">​</a></h2><ol><li>Open <strong>Settings → Live Chat</strong> (requires <code>live-chat.manage</code>), or use <strong>Settings</strong> from the Live Chat desk.</li><li>Set greeting, branding (color, launcher text, position, header, logo, agent display name), and optionally require name/email before chat starts.</li><li>Add <strong>suggested replies</strong> (quick-reply chips in the visitor widget).</li><li>Optionally show <strong>Powered by EloSync</strong> on the widget footer.</li><li>Configure <strong>business hours</strong> (workspace timezone). Outside hours, visitors see the offline greeting and can leave a message when offline mode is enabled.</li><li>Optionally enable <strong>email notify agents</strong> for inbound/offline messages.</li><li>Copy the embed snippet onto your website (script loads from your EloSync API host).</li><li>Keep the widget <strong>Active</strong> so visitors can start conversations.</li></ol><p>Visitors keep their chat across page refreshes on the same browser (session stored locally until it expires or you regenerate the public key). The pre-chat Name / Email fields use dark labels so they stay readable on any host site theme.</p><p>Regenerating the public key invalidates existing embeds until you update the snippet.</p><h2 id="agent-desk" tabindex="-1">Agent desk <a class="header-anchor" href="#agent-desk" aria-label="Permalink to &quot;Agent desk&quot;">​</a></h2><p>Tabs under <strong>Live Chat</strong>:</p><ul><li><strong>Overview</strong> — visitors today, chats answered/missed, page views (7d), recent history.</li><li><strong>Inbox</strong> — fullscreen 3-pane shell (list, thread, visitor panel).</li><li><strong>Live visitors</strong> — who is on site (heartbeat window); open or start a chat.</li></ul><h3 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to &quot;Inbox&quot;">​</a></h3><ul><li>Conversation list filters: All, Unread, Mine, Unassigned, Open, Closed, Offline.</li><li>Thread header: Claim, Close/Reopen, Escalate. Assign, lead link, and ban live in the visitor panel.</li><li>Composer: <strong>Reply</strong> (visitor-visible) or <strong>Note</strong> (internal only). Attach files from the composer.</li><li>Insert <strong>canned replies</strong> from Reply mode (manage canned replies in Settings → Live Chat).</li><li>Visitor panel shows IP, country, browser/OS, page, referrer, pages viewed, last seen.</li><li>Search filters by visitor name, email, page URL, or message preview.</li><li>New visitor messages update in near-realtime when Echo/Reverb is connected (polling remains as fallback).</li></ul><h2 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h2><p>Create departments under <strong>Settings → Live Chat</strong> (<code>live-chat.manage</code>), assign agents, and set a default department on the widget for new conversations.</p><h2 id="leads" tabindex="-1">Leads <a class="header-anchor" href="#leads" aria-label="Permalink to &quot;Leads&quot;">​</a></h2><p>When <strong>Leads</strong> is installed:</p><ul><li>Search and link an existing lead, or create a new lead from the visitor panel and auto-link it.</li><li>Unlink anytime. Linking requires <code>live-chat.reply</code> or <code>live-chat.manage</code> plus Leads access.</li></ul><h2 id="help-desk" tabindex="-1">Help Desk <a class="header-anchor" href="#help-desk" aria-label="Permalink to &quot;Help Desk&quot;">​</a></h2><p>When <strong>Help Desk</strong> is installed, escalate a conversation to a ticket from the thread (<code>live-chat.reply</code> plus Help Desk create permission). The conversation keeps a soft link to the ticket.</p><h2 id="moderation" tabindex="-1">Moderation <a class="header-anchor" href="#moderation" aria-label="Permalink to &quot;Moderation&quot;">​</a></h2><p>With <code>live-chat.manage</code>, ban a visitor from the visitor panel. Banned visitors cannot start new sessions.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>New visitor messages create an in-app notification that opens <code>/live-chat?conversation={uuid}</code>. Optional email notify (widget setting) alerts agents when configured.</p>',22)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
